ROOT.scriptdef:
CREATE PROCEDURE [CDN].[POS_IloscTowary]
	@rowVersion bigint,
	@pointOfSaleId int,
	@packageSize int,
	@packagesCount int output,
	@currentRowVersion bigint output 
AS
BEGIN
	SET NOCOUNT ON;		
		select @currentRowVersion=max(TwrLastMod),@packagesCount=CEILING(cast(count(*) as float)/@packageSize) from CDN.POS_TwrDoEksportu(@pointOfSaleId,@rowVersion)
		select @currentRowVersion=isnull(@currentRowVersion,@rowVersion),@packagesCount=isnull(@packagesCount,0)
	SET NOCOUNT OFF;	
END
